contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: deposit some Ether as this contract, then call withdraw and check invariant
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before
        uint beforeContractBal = address(c).balance;
        uint beforeRecorded = c.getBalance(address(this));

        // perform a deposit to c from this contract
        c.addToBalance{value: depositAmount}();

        // record after-deposit values
        uint afterContractBal = address(c).balance;
        uint afterRecorded = c.getBalance(address(this));

        // sanity: after deposit, both recorded and contract balance should have increased by depositAmount
        // (put as require so failure doesn't make assert unreachable)
        require(afterContractBal >= beforeContractBal);
        require(afterRecorded >= beforeRecorded);

        // now attempt withdrawal and capture whether it reverts
        bool withdrew;
        try c.withdrawBalance() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // values after withdrawal
        uint finalContractBal = address(c).balance;
        uint finalRecorded = c.getBalance(address(this));

        // General rule: if withdrawal call succeeded then the recorded balance for this contract is zero,
        // and the contract's ether balance decreased by at most the amount that had been recorded for this caller before withdraw.
        // If withdrawal reverted, recorded balance must remain unchanged.
        assert( (withdrew && finalRecorded == 0 && (beforeRecorded + depositAmount) >= (afterContractBal - finalContractBal))
                || (!withdrew && finalRecorded == afterRecorded) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller is this contract when interacting with c
    function run(uint deposit) public payable {
        require(address(this).balance >= deposit);
        // observe before values
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        // perform the state-changing call: send Ether deposit to c via addToBalance
        try c.addToBalance{value: deposit}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBalance = address(c).balance;

        // If the call reverted, recorded and contract balances must be unchanged.
        // If it succeeded, recorded balance must increase by deposit and contract balance must increase by deposit.
        assert(
            (reverted && afterRecorded == beforeRecorded && afterContractBalance == beforeContractBalance)
            || (!reverted && afterRecorded == beforeRecorded + deposit && afterContractBalance == beforeContractBalance + deposit)
        );
    }

    // allow receiving refunds when withdrawBalance is called on c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: depositAmount then attempt withdraw; check properties
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record contract balance and user recorded balance before depositing
        uint beforeContractBal = address(c).balance;
        uint beforeRecorded = c.getBalance(address(this));

        // deposit depositAmount into c on behalf of this contract
        c.addToBalance{value: depositAmount}();

        // after deposit, recorded balance must have increased by depositAmount
        uint afterRecorded = c.getBalance(address(this));
        // call withdraw and observe whether it reverts
        bool reverted;
        uint contractBalBeforeWithdraw = address(c).balance;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint contractBalAfterWithdraw = address(c).balance;
        uint recordedAfter = c.getBalance(address(this));

        // General rule combining both revert and non-revert cases:
        // - If withdraw succeeded (not reverted): recordedAfter == 0 and the contract's balance did not decrease by more than the prior recorded amount (i.e., at most contractBalBeforeWithdraw - contractBalAfterWithdraw <= (beforeRecorded + depositAmount)).
        // - If withdraw reverted: recordedAfter equals the value before withdraw (no change) and contract balance unchanged.
        assert(
            (!reverted && recordedAfter == 0 && (contractBalBeforeWithdraw - contractBalAfterWithdraw) <= (beforeRecorded + depositAmount))
            || (reverted && recordedAfter == afterRecorded && contractBalBeforeWithdraw == contractBalAfterWithdraw)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an arbitrary deposit amount and attempt to add it.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // read balance before
        uint before = c.getBalance(address(this));

        // attempt deposit and record whether it reverted
        bool reverted;
        try c.addToBalance{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after (always allowed; view function)
        uint after = c.getBalance(address(this));

        // General rule: if the deposit call succeeded, the recorded balance for this caller
        // did not decrease and is at least the deposited amount (i.e., after >= amount)
        // Note: after >= before is implied by non-decrease; we assert both.
        assert(reverted || (after >= before && after >= amount));
    }

    receive() external payable {}
}
